43	export async function createRepository(dataFilePath: string): Promise<Repository> {
44	  const existingState = await readExistingState(dataFilePath);
45	  let state: State = existingState ?? emptyState();
46	
47	  if (existingState === null) {
48	    await writeStateAtomically(dataFilePath, state);
49	  }
