51	  // Serializes mutate() calls: each call is chained onto the previous one,
52	  // so read -> decide -> write per call runs atomically with respect to others (AD-3).
53	  let queue: Promise<unknown> = Promise.resolve();
54	
55	  function mutate<R>(fn: (state: State) => { state: State; result: R }): Promise<R> {
56	    const task = queue.then(async () => {
57	      const { state: nextState, result } = fn(state);
58	      await writeStateAtomically(dataFilePath, nextState);
59	      state = nextState;
